// pipe. Without them an agent can read a misconfiguration and not act on it.
func TestScanResultCarriesAMisconfigurationsSpan(t *testing.T) {
	fakeCacheHome(t)
	stubImages(t, "app:1.0")
	storeImageResult(t, "app:1.0", &scan.Result{
