// MCP server and a calling agent handle.
func TestARuleOutsideTheCatalogHasNoFix(t *testing.T) {
	if _, ok := FixFor(misconf("AVD-DS-0026", "Dockerfile")); ok {
		t.Error("an uncatalogued rule was offered a fix")
